\documentclass[conference]{IEEEtran}
\IEEEoverridecommandlockouts
\usepackage{cite}
\usepackage{amsmath,amssymb,amsfonts}
\usepackage{graphicx}
\usepackage{hyperref}

\begin{document}

\title{Your Paper Title Here}

\author{
  \IEEEauthorblockN{First Author}
  \IEEEauthorblockA{\textit{Affiliation} \\
  City, Country \\
  first.author@example.com}
}

\maketitle

\begin{abstract}
Replace with a 150-word abstract describing the problem, approach, and key result.
\end{abstract}

\begin{IEEEkeywords}
keyword, keyword, keyword
\end{IEEEkeywords}

\section{Introduction}
Motivate the problem, summarise contributions, and outline the paper.

\section{Related Work}
Discuss prior art~\cite{example2024}.

\section{Method}
Describe the approach. Reference Equation~\eqref{eq:example}:
\begin{equation}
  y = f(x) + \epsilon
  \label{eq:example}
\end{equation}

\section{Results}
Report experiments. Reference Figure~\ref{fig:example} as needed.

\section{Conclusion}
Summarise findings and outline future work.

\bibliographystyle{IEEEtran}
\bibliography{references}

\end{document}

@article{example2024,
  author  = {Doe, Jane},
  title   = {An Illustrative Example of a Bibliography Entry},
  journal = {Journal of Examples},
  year    = {2024},
  volume  = {1},
  number  = {1},
  pages   = {1--10}
}

