\documentclass[12pt,a4paper,oneside]{report}
\usepackage[utf8]{inputenc}
\usepackage[T1]{fontenc}
\usepackage{lmodern}
\usepackage[english]{babel}
\usepackage{geometry}
\geometry{margin=2.5cm}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{hyperref}

\title{Your Thesis Title}
\author{Your Name}
\date{\today}

\begin{document}

\maketitle

\begin{abstract}
Replace with the abstract of your thesis.
\end{abstract}

\tableofcontents

\input{chapters/introduction.tex}
\input{chapters/background.tex}
\input{chapters/method.tex}
\input{chapters/results.tex}
\input{chapters/conclusion.tex}

\bibliographystyle{plain}
\bibliography{references}

\end{document}

\chapter{Introduction}
\label{ch:introduction}

Motivate the problem and outline the structure of the thesis.

\chapter{Background}
\label{ch:background}

Review foundational concepts the rest of the thesis builds on.

\chapter{Method}
\label{ch:method}

Describe the approach, hypotheses, and design decisions.

\chapter{Results}
\label{ch:results}

Report experiments, observations, and statistical analysis.

\chapter{Conclusion}
\label{ch:conclusion}

Summarise contributions and propose directions for future work.

