\pagestyle{fancy}
\fancyhf{}
\lhead{Course Name --- Assignment N}
\rhead{Your Name}
\cfoot{\thepage}

\theoremstyle{definition}
\newtheorem{exercise}{Exercise}
\newtheorem*{solution*}{Solution}

\title{Assignment N}
\author{Your Name}
\date{\today}

\begin{document}
\maketitle

\begin{exercise}
  State the first problem here, verbatim from the course.
\end{exercise}
\begin{solution*}
  Write out the solution. Use equations and proof environments freely:
  \[
    \int_0^1 x^2 \, dx = \tfrac{1}{3}.
  \]
\end{solution*}

\begin{exercise}
  State the second problem.
\end{exercise}
\begin{solution*}
  Solution to the second problem.
\end{solution*}

\end{document}

